# ==============================================================================
# SERVER
# ==============================================================================
server <- function(input, output, session) {
  
  asistencia_parseada <- reactiveVal(list())
  notas_parseadas     <- reactiveVal(list())
  pdd_parseada        <- reactiveVal(list())
  
  datos_modal_rojos  <- reactiveVal(NULL)
  datos_modal_rangos <- reactiveVal(NULL)
  datos_modal_pdd    <- reactiveVal(NULL)
  
  agregar_archivos <- function(x, almacen, procesador, etiqueta) {
    if (is.null(x) || nrow(x) == 0) return(invisible())
    x$id <- paste(x$name, x$size, sep = "|")
    actual <- almacen()
    nuevos <- x[!x$id %in% names(actual), , drop = FALSE]
    if (nrow(nuevos) == 0) return(invisible())
    
    withProgress(message = paste("Leyendo", etiqueta), value = 0, {
      for (i in seq_len(nrow(nuevos))) {
        incProgress(1 / nrow(nuevos), detail = nuevos$name[i])
        actual[[nuevos$id[i]]] <- procesador(nuevos$datapath[i], nuevos$name[i])
      }
    })
    almacen(actual)
  }
  
  observeEvent(input$archivo_excel, agregar_archivos(input$archivo_excel, asistencia_parseada, procesar_asistencia, "asistencia"), ignoreInit = TRUE)
  observeEvent(input$archivo_notas, agregar_archivos(input$archivo_notas, notas_parseadas, procesar_notas, "notas"), ignoreInit = TRUE)
  observeEvent(input$archivo_pdd, agregar_archivos(input$archivo_pdd, pdd_parseada, procesar_pdd, "PDD"), ignoreInit = TRUE)
  
  observeEvent(input$btn_limpiar, {
    asistencia_parseada(list()); notas_parseadas(list()); pdd_parseada(list())
    showNotification("Todos los datos fueron borrados.", type = "message")
  })
  
  todos_los_cursos <- reactive({
    ok <- Filter(function(e) isTRUE(e$ok), asistencia_parseada())
    if (length(ok) == 0) return(list())
    todo <- bind_rows(lapply(ok, function(e) e$res))
    split(todo, todo$Curso)
  })
  
  asist_cargada <- reactive(length(todos_los_cursos()) > 0)
  
  datos_globales <- reactive({
    cursos <- todos_los_cursos()
    if (length(cursos) == 0) return(asist_vacia)
    bind_rows(cursos) %>% mutate(Mes = factor(tolower(as.character(Mes)), levels = orden_meses))
  })
  
  asist_resumen <- reactive({
    d <- datos_globales()
    if (nrow(d) == 0) return(asist_res_vacio)
    d %>%
      mutate(Dia_num = suppressWarnings(as.integer(as.numeric(Dia))), Dia_num = ifelse(is.na(Dia_num), 0L, Dia_num)) %>%
      arrange(Curso, Nombre, Mes, Dia_num) %>%
      group_by(Curso, Nombre) %>%
      summarise(Dias = n(), Asistidos = sum(Estado == "Asistió"), Faltas = sum(Estado == "Faltó"), Pct = Asistidos / Dias * 100, MaxRacha = racha_max(Estado == "Faltó"), .groups = "drop") %>%
      mutate(Categoria = categoria_asistencia(Pct))
  })
  
  notas_data <- reactive({
    entradas <- Filter(function(e) isTRUE(e$ok), notas_parseadas())
    if (length(entradas) == 0) return(list(det = det_vacio, prom = prom_vacio, vinc = vinc_vacio))
    
    asist <- todos_los_cursos()
    cursos_asist <- names(asist)
    info_c <- lapply(entradas, function(e) {
      ca <- emparejar_curso(e$res$info, cursos_asist)
      list(curso = if (is.na(ca)) paste0(etiqueta_curso(e$res$info), " (solo notas)") else ca, con_asist = !is.na(ca))
    })
    cursos <- vapply(info_c, function(x) x$curso, character(1))
    
    vinc_l <- list()
    for (cu in unique(cursos)) {
      idx <- which(cursos == cu)
      nombres_notas <- unique(unlist(lapply(entradas[idx], function(e) e$res$nombres)))
      nombres_notas <- nombres_notas[es_nombre_alumno(nombres_notas)]
      if (length(nombres_notas) == 0) next
      alumnos_asist <- if (cu %in% cursos_asist) unique(asist[[cu]]$Nombre) else character(0)
      mapeo <- emparejar_uno_a_uno(alumnos_asist, nombres_notas)
      vinc_l[[length(vinc_l) + 1]] <- data.frame(
        Curso = cu, Nombre_Notas = nombres_notas, Alumno = ifelse(is.na(mapeo), nombres_notas, unname(mapeo)),
        Vinculado = !is.na(mapeo), Curso_con_asistencia = cu %in% cursos_asist, stringsAsFactors = FALSE
      )
    }
    vinc <- if (length(vinc_l) > 0) bind_rows(vinc_l) else vinc_vacio
    mapa <- vinc[, c("Curso", "Nombre_Notas", "Alumno", "Vinculado")]
    
    det_l <- list(); prom_l <- list()
    for (k in seq_along(entradas)) {
      r <- entradas[[k]]$res
      if (nrow(r$det) > 0)  { d <- r$det;  d$Curso <- cursos[k]; det_l[[length(det_l) + 1]]   <- d }
      if (nrow(r$prom) > 0) { p <- r$prom; p$Curso <- cursos[k]; prom_l[[length(prom_l) + 1]] <- p }
    }
    
    det <- if (length(det_l) > 0) left_join(bind_rows(det_l), mapa, by = c("Curso", "Nombre_Notas")) else det_vacio
    prom <- if (length(prom_l) > 0) left_join(bind_rows(prom_l), mapa, by = c("Curso", "Nombre_Notas")) else prom_vacio
    
    list(det = det %>% filter(es_nombre_alumno(Alumno)), prom = prom %>% filter(es_nombre_alumno(Alumno)), vinc = vinc)
  })
  
  notas_cargadas <- reactive(nrow(notas_data()$det) > 0 || nrow(notas_data()$prom) > 0)
  
  filtra_asig <- function(df) {
    if (nrow(df) == 0 || is.null(input$select_asignatura) || input$select_asignatura == "Todas") return(df)
    df %>% filter(Asignatura == input$select_asignatura)
  }
  filtra_sem <- function(df) {
    if (nrow(df) == 0 || is.null(input$select_semestre) || input$select_semestre == "Todos") return(df)
    sem <- suppressWarnings(as.integer(gsub("[^0-9]", "", input$select_semestre)))
    df %>% filter(Semestre == sem)
  }
  
  observeEvent(notas_data(), {
    nd <- notas_data()
    choices <- c("Todas", sort(unique(c(nd$det$Asignatura, nd$prom$Asignatura))))
    updateSelectInput(session, "select_asignatura", choices = choices)
    semestres <- sort(unique(c(nd$det$Semestre, nd$prom$Semestre)))
    updateSelectInput(session, "select_semestre", choices = c("Todos", paste("Semestre", semestres[!is.na(semestres)])))
  })
  
  prom_base <- reactive({
    nd <- notas_data()
    if (nrow(nd$det) == 0 && nrow(nd$prom) == 0) return(prom_vacio)
    calc <- nd$det %>% filter(!is.na(Alumno)) %>% group_by(Curso, Asignatura, Alumno, Semestre) %>% summarise(Prom_calc = round(mean(Nota), 1), .groups = "drop")
    p <- nd$prom %>% filter(!is.na(Alumno)) %>% select(Curso, Asignatura, Alumno, Semestre, Promedio)
    if (nrow(calc) > 0) p <- full_join(p, calc, by = c("Curso", "Asignatura", "Alumno", "Semestre")) %>% mutate(Promedio = ifelse(is.na(Promedio), Prom_calc, Promedio))
    p <- filtra_sem(p %>% filter(!is.na(Promedio)))
    if (nrow(p) == 0) return(prom_vacio)
    p %>% group_by(Curso, Asignatura, Alumno) %>% summarise(Promedio = round(mean(Promedio), 1), .groups = "drop")
  })
  
  prom_filtrado <- reactive(filtra_asig(prom_base()))
  det_filtrado <- reactive(filtra_asig(filtra_sem(notas_data()$det)))
  prom_curso <- reactive({ req(input$select_curso); p <- prom_filtrado(); if (input$select_curso == "TODOS") p else p %>% filter(Curso == input$select_curso) })
  
  pdd_data <- reactive({
    entradas <- Filter(function(e) isTRUE(e$ok), pdd_parseada())
    if (length(entradas) == 0) return(pdd_vacio)
    d <- bind_rows(lapply(entradas, function(e) e$res))
    catalogo <- unique(c(names(todos_los_cursos()), notas_data()$vinc$Curso))
    cursos_u <- unique(d$Curso)
    map_c <- vapply(cursos_u, function(cu) { ca <- emparejar_curso(parsear_curso(cu), catalogo); if (is.na(ca)) cu else ca }, character(1))
    d$Curso_Canon <- unname(map_c[d$Curso])
    
    ref_all <- bind_rows(if (asist_cargada()) datos_globales() %>% distinct(Curso, Alumno = Nombre) else data.frame(Curso = character(), Alumno = character()), notas_data()$vinc %>% distinct(Curso, Alumno)) %>% distinct()
    d$Alumno_Canon <- d$Alumno
    d$Vinculado <- FALSE
    for (cc in unique(d$Curso_Canon)) {
      ref <- unique(ref_all$Alumno[ref_all$Curso == cc])
      if (length(ref) == 0) next
      idx <- which(d$Curso_Canon == cc)
      mp <- emparejar_uno_a_uno(ref, unique(d$Alumno[idx]))
      rep_n <- unname(mp[d$Alumno[idx]])
      ok <- !is.na(rep_n)
      d$Alumno_Canon[idx[ok]] <- rep_n[ok]
      d$Vinculado[idx[ok]] <- TRUE
    }
    d
  })
  
