    base <- bind_rows(a[, c("Curso", "Alumno")], n[, c("Curso", "Alumno")], p[, c("Curso", "Alumno")]) %>% distinct()
    if (nrow(base) == 0) return(data.frame(Curso = character(), Alumno = character(), stringsAsFactors = FALSE))
    
    base %>%
      left_join(a, by = c("Curso", "Alumno")) %>%
      left_join(n, by = c("Curso", "Alumno")) %>%
      left_join(p, by = c("Curso", "Alumno")) %>%
