    d <- inner_join(n, p, by = c("Curso", "Alumno", "Asignatura")) %>% mutate(Dif = Nota_Colegio - Nota_PDD) %>% filter(abs(Dif) >= 1.5)
    validate(need(nrow(d) > 0, "Sin discrepancias mayores a 1.5."))
    d %>% transmute(Curso = etiquetar(Curso), Alumno, Asignatura, `Nota Colegio` = sprintf("%.1f", Nota_Colegio), `Nota PDD` = sprintf("%.1f", Nota_PDD), Diferencia = sprintf("%+.1f", Dif))
  }, striped = TRUE, hover = TRUE)
  
  # Vista por curso / alumno
  output$plot_porcentaje <- renderPlot({
    res <- datos_procesados()$datos; validate(need(nrow(res) > 0, "Sin datos."))
    p <- res %>% group_by(Nombre) %>% summarise(Pct = mean(Estado == "Asistió") * 100, .groups = "drop")
    ggplot(p, aes(x = reorder(Nombre, Pct), y = Pct)) + geom_col(fill = col_azul, width = 0.6) + geom_hline(yintercept = UMBRAL_ASIST, color = col_rojo, linetype = "dashed") + coord_flip() + scale_y_continuous(limits = c(0, 105)) + labs(x = NULL, y = "% Asistencia") + tema_dash()
  })
  
  output$tabla_rachas <- renderTable({
    d <- asist_resumen(); validate(need(nrow(d) > 0, "Sin datos."))
    d %>% transmute(Curso = etiquetar(Curso), Alumno = Nombre, `% Asistencia` = sprintf("%.1f%%", Pct), Faltas, `Racha Máx.` = MaxRacha, Categoría)
  }, striped = TRUE, hover = TRUE)
  
  output$plot_evolucion <- renderPlot({
    res <- datos_procesados()$datos %>% filter(!is.na(Mes)); validate(need(nrow(res) > 0, "Sin datos."))
    evo <- res %>% group_by(Mes) %>% summarise(Pct = mean(Estado == "Asistió") * 100, .groups = "drop")
    ggplot(evo, aes(x = Mes, y = Pct, group = 1)) + geom_line(color = col_azul, linewidth = 1) + geom_point(size = 3) + scale_y_continuous(limits = c(50, 100)) + labs(x = NULL, y = "% Asistencia") + tema_dash()
  })
  
  output$plot_acumulado <- renderPlot({
    res <- datos_procesados()$datos; validate(need(nrow(res) > 0, "Sin datos."))
    ggplot(res, aes(x = Nombre, fill = Estado)) + geom_bar() + scale_fill_manual(values = c("Asistió" = col_azul, "Faltó" = col_rojo)) + labs(x = NULL, y = "Días") + tema_dash() + theme(axis.text.x = element_text(angle = 70, hjust = 1))
  })
  
  output$plot_anillo <- renderPlot({
    req(input$select_alumno)
    da <- datos_procesados()$datos %>% filter(Nombre == input$select_alumno); validate(need(nrow(da) > 0, "Sin datos."))
    tot <- nrow(da); asist <- sum(da$Estado == "Asistió"); pct <- asist / tot * 100
    df <- data.frame(Estado = c("Asistió", "Faltó"), Cant = c(asist, tot - asist))
    ggplot(df, aes(x = 2, y = Cant, fill = Estado)) + geom_bar(stat = "identity", width = 0.8) + coord_polar(theta = "y") + xlim(c(0.5, 2.5)) + scale_fill_manual(values = c("Asistió" = col_azul, "Faltó" = col_rojo)) + theme_void() + labs(title = sprintf("%.1f%% Asistencia", pct))
  })
  
  output$plot_treemap <- renderPlot({
    req(input$select_alumno)
    da <- datos_procesados()$datos %>% filter(Nombre == input$select_alumno, !is.na(Mes)) %>% group_by(Mes, Estado) %>% summarise(Cantidad = n(), .groups = "drop")
    validate(need(nrow(da) > 0, "Sin datos."))
    ggplot(da, aes(area = Cantidad, fill = Estado, subgroup = Mes, label = paste0(Mes, "\n", Estado, ": ", Cantidad))) + geom_treemap() + geom_treemap_text(colour = "white", place = "center") + scale_fill_manual(values = c("Asistió" = col_azul, "Faltó" = col_rojo))
  })
  
  output$tabla_dias <- renderTable({
    req(input$select_alumno)
    res <- datos_procesados()$datos %>% filter(Nombre == input$select_alumno) %>% select(Mes, Dia, Estado)
    colnames(res) <- c("Mes", "Día", "Estado"); res
  }, striped = TRUE, hover = TRUE)
  
  output$plot_notas_alumno <- renderPlot({
    validate(need(notas_cargadas(), "Sin notas."))
    d <- pg_alumno(prom_curso()); validate(need(nrow(d) > 0, "Sin datos."))
    ggplot(d, aes(x = reorder(Alumno, PG), y = PG)) + geom_col(fill = col_azul, width = 0.6) + geom_hline(yintercept = NOTA_ROJA, color = col_rojo, linetype = "dashed") + coord_flip() + scale_y_continuous(limits = c(0, 7.5)) + labs(x = NULL, y = "Promedio") + tema_dash()
  })
  
  output$tabla_ranking <- renderTable({
    validate(need(notas_cargadas(), "Sin notas."))
    d <- pg_alumno(prom_curso()); validate(need(nrow(d) > 0, "Sin datos."))
    d %>% arrange(desc(PG)) %>% mutate(Puesto = min_rank(desc(PG))) %>% transmute(Puesto, Alumno, Promedio = sprintf("%.1f", PG), `Asig. Rojas` = N_Rojas)
  }, striped = TRUE, hover = TRUE)
  
  output$plot_notas_asig_box <- renderPlot({
    validate(need(notas_cargadas(), "Sin notas."))
    d <- prom_curso(); validate(need(nrow(d) > 0, "Sin datos."))
    ggplot(d, aes(x = Asignatura, y = Promedio)) + geom_boxplot(fill = col_azul, alpha = 0.4) + geom_jitter(width = 0.1) + scale_y_continuous(limits = c(1, 7)) + tema_dash()
  })
  
  output$plot_notas_asig_rango <- renderPlot({
    validate(need(notas_cargadas(), "Sin notas."))
    d <- prom_curso() %>% mutate(Rango = rangos_nota(Promedio)) %>% count(Asignatura, Rango)
    ggplot(d, aes(x = Asignatura, y = n, fill = Rango)) + geom_col(width = 0.6) + scale_fill_manual(values = colores_rango) + labs(x = NULL, y = "Alumnos") + tema_dash()
  })
  
  output$plot_notas_evolucion <- renderPlot({
    validate(need(notas_cargadas(), "Sin notas."))
    d <- det_filtrado() %>% group_by(Asignatura, Etiqueta) %>% summarise(Prom = mean(Nota), .groups = "drop")
    ggplot(d, aes(x = Etiqueta, y = Prom, color = Asignatura, group = Asignatura)) + geom_line(linewidth = 1) + geom_point(size = 3) + scale_y_continuous(limits = c(1, 7)) + labs(x = NULL, y = "Nota Promedio") + tema_dash()
  })
  
  output$resumen_alumno <- renderUI({
    req(input$select_alumno)
    d <- pg_alumno(prom_curso()) %>% filter(Alumno == input$select_alumno)
    validate(need(nrow(d) > 0, "Sin notas."))
    wellPanel(p(sprintf("Alumno: %s | Promedio: %.1f | Asignaturas Rojas: %d", d$Alumno, d$PG, d$N_Rojas)))
  })
  
  output$plot_alumno_asig <- renderPlot({
    req(input$select_alumno)
    da <- prom_curso() %>% filter(Alumno == input$select_alumno)
    validate(need(nrow(da) > 0, "Sin notas."))
    ggplot(da, aes(x = Asignatura, y = Promedio)) + geom_col(fill = col_azul, width = 0.6) + geom_hline(yintercept = NOTA_ROJA, color = col_rojo, linetype = "dashed") + scale_y_continuous(limits = c(0, 7.5)) + labs(x = NULL, y = "Promedio") + tema_dash()
  })
  
  output$plot_alumno_evol <- renderPlot({
    req(input$select_alumno)
    da <- det_filtrado() %>% filter(Alumno == input$select_alumno)
    validate(need(nrow(da) > 0, "Sin notas."))
    ggplot(da, aes(x = Etiqueta, y = Nota, color = Asignatura, group = Asignatura)) + geom_line(linewidth = 1) + geom_point(size = 3) + scale_y_continuous(limits = c(1, 7)) + labs(x = NULL, y = "Nota") + tema_dash()
  })
  
  output$tabla_notas_alumno <- renderTable({
    req(input$select_alumno)
    dd <- det_filtrado() %>% filter(Alumno == input$select_alumno)
    validate(need(nrow(dd) > 0, "Sin datos."))
    dd %>% group_by(Asignatura, Etiqueta) %>% summarise(Nota = mean(Nota), .groups = "drop") %>% pivot_wider(names_from = Etiqueta, values_from = Nota)
  }, striped = TRUE, hover = TRUE)
  
  # PDD Seccion
  pdd_filtrado <- reactive({
    d <- pdd_data(); if (nrow(d) == 0) return(d)
    if (!is.null(input$pdd_filtro_curso) && input$pdd_filtro_curso != "Todos los cursos evaluados") d <- d %>% filter(Curso == input$pdd_filtro_curso)
    if (!is.null(input$pdd_filtro_asig) && input$pdd_filtro_asig != "Todas") d <- d %>% filter(Asignatura == input$pdd_filtro_asig)
    d
  })
  
  pdd_nomina_filtrada <- reactive({
    d <- pdd_data(); if (nrow(d) == 0) return(d)
    if (!is.null(input$pdd_nom_curso) && input$pdd_nom_curso != "Todos los cursos") d <- d %>% filter(Curso == input$pdd_nom_curso)
    if (!is.null(input$pdd_nom_asig) && input$pdd_nom_asig != "Todas las asignaturas") d <- d %>% filter(Asignatura == input$pdd_nom_asig)
    if (!is.null(input$pdd_nom_nivel) && input$pdd_nom_nivel != "Todos los niveles") d <- d %>% filter(Nivel_Logro == input$pdd_nom_nivel)
    if (!is.null(input$pdd_nom_genero) && input$pdd_nom_genero != "TODOS") d <- d %>% filter(Sexo == input$pdd_nom_genero)
    if (!is.null(input$pdd_nom_busqueda) && nzchar(trimws(input$pdd_nom_busqueda))) {
      q_norm <- norm_txt(trimws(input$pdd_nom_busqueda))
      d <- d[grepl(q_norm, norm_txt(d$Alumno), fixed = TRUE) | grepl(q_norm, norm_txt(d$RUT), fixed = TRUE), , drop = FALSE]
    }
    d
  })
  
  output$kpi_pdd_logro <- renderText({ d <- pdd_filtrado(); if (nrow(d) == 0) "s/d" else sprintf("%.1f%%", mean(d$Logro, na.rm = TRUE)) })
  output$kpi_pdd_nota <- renderText({ d <- pdd_filtrado(); if (nrow(d) == 0) "s/d" else sprintf("%.2f", mean(d$Nota, na.rm = TRUE)) })
  output$kpi_pdd_evaluados <- renderText({ d <- pdd_filtrado(); if (nrow(d) == 0) "0" else as.character(length(unique(d$RUT))) })
  output$kpi_pdd_insuficiente <- renderText({ d <- pdd_filtrado(); if (nrow(d) == 0) "s/d" else sprintf("%.1f%%", mean(d$Logro < UMBRAL_LOGRO_ELEM, na.rm = TRUE) * 100) })
  
  output$plot_pdd_cursos <- renderPlot({
    d <- pdd_filtrado(); validate(need(nrow(d) > 0, "Sin datos PDD."))
    res <- d %>% group_by(Curso, Asignatura) %>% summarise(Logro_Medio = mean(Logro, na.rm = TRUE), .groups = "drop")
    ggplot(res, aes(x = reorder(Curso, Logro_Medio), y = Logro_Medio, fill = Asignatura)) + geom_col(position = "dodge", width = 0.7) + coord_flip() + scale_y_continuous(limits = c(0, 100)) + scale_fill_manual(values = paleta_cat) + labs(x = NULL, y = "% Logro") + tema_dash()
  })
  
  output$plot_pdd_semaforo <- renderPlot({
    d <- pdd_filtrado(); validate(need(nrow(d) > 0, "Sin datos PDD."))
    cnt <- d %>% filter(!is.na(Nivel_Logro)) %>% count(Curso, Nivel_Logro)
    ggplot(cnt, aes(x = Curso, y = n, fill = Nivel_Logro)) + geom_col(position = "fill", width = 0.6) + coord_flip() + scale_fill_manual(values = colores_logro) + labs(x = NULL, y = "Proporción") + tema_dash()
  })
  
  output$plot_pdd_genero <- renderPlot({
    d <- pdd_filtrado() %>% filter(!is.na(Sexo)); validate(need(nrow(d) > 0, "Sin datos de género."))
    res <- d %>% group_by(Asignatura, Sexo) %>% summarise(Logro_Medio = mean(Logro, na.rm = TRUE), .groups = "drop")
    ggplot(res, aes(x = Asignatura, y = Logro_Medio, fill = Sexo)) + geom_col(position = "dodge", width = 0.6) + scale_y_continuous(limits = c(0, 100)) + labs(x = NULL, y = "% Logro") + tema_dash()
  })
  
  output$plot_pdd_dist <- renderPlot({
    d <- pdd_filtrado(); validate(need(nrow(d) > 0, "Sin datos PDD."))
    ggplot(d, aes(x = Curso, y = Nota, fill = Asignatura)) + geom_boxplot(alpha = 0.5) + scale_y_continuous(limits = c(1, 7)) + labs(x = NULL, y = "Nota PDD") + tema_dash()
  })
  
  output$pdd_contador_nomina <- renderUI({
    tags$div(class = "text-muted mb-2", sprintf("Mostrando %d de %d registros.", nrow(pdd_nomina_filtrada()), nrow(pdd_data())))
  })
  
  output$tabla_pdd_estudiantes <- renderTable({
    d <- pdd_nomina_filtrada(); validate(need(nrow(d) > 0, "Sin resultados."))
    d %>% transmute(Curso, `Alumno` = Alumno, RUT, Sexo, Asignatura, `% Logro` = sprintf("%.0f%%", Logro), `Nota PDD` = sprintf("%.1f", Nota), `Nivel` = Nivel_Logro)
  }, striped = TRUE, hover = TRUE)
  
  # Control de Carga
  output$tabla_cobertura <- renderTable({
    a <- if (asist_cargada()) datos_globales() %>% group_by(Curso) %>% summarise(Asistencia = n_distinct(Nombre), .groups = "drop") else data.frame(Curso = character(), Asistencia = integer())
    nd <- notas_data()
    n <- if (nrow(nd$det) + nrow(nd$prom) > 0) bind_rows(nd$det[, c("Curso", "Asignatura")], nd$prom[, c("Curso", "Asignatura")]) %>% distinct() %>% count(Curso, name = "Notas") else data.frame(Curso = character(), Notas = integer())
    p <- if (pdd_cargado()) pdd_data() %>% group_by(Curso = Curso_Canon) %>% summarise(PDD = n_distinct(Asignatura), .groups = "drop") else data.frame(Curso = character(), PDD = integer())
    
    cursos <- unique(c(a$Curso, n$Curso, p$Curso)); validate(need(length(cursos) > 0, "Sin archivos cargados."))
    data.frame(Curso = cursos, stringsAsFactors = FALSE) %>%
      left_join(a, by = "Curso") %>% left_join(n, by = "Curso") %>% left_join(p, by = "Curso") %>%
      transmute(Curso = etiquetar(Curso), Asistencia = ifelse(is.na(Asistencia), "FALTA", as.character(Asistencia)), Notas = ifelse(is.na(Notas), "FALTA", as.character(Notas)), PDD = ifelse(is.na(PDD), "FALTA", as.character(PDD)))
  }, striped = TRUE, hover = TRUE)
  
  output$tabla_archivos <- renderTable({
    ent <- c(unname(asistencia_parseada()), unname(notas_parseadas()), unname(pdd_parseada()))
    validate(need(length(ent) > 0, "Sin archivos cargados."))
    bind_rows(lapply(ent, function(e) data.frame(Archivo = e$nombre, Tipo = e$tipo, Curso = e$curso_txt, Estado = e$estado, Detalle = e$detalle, check.names = FALSE, stringsAsFactors = FALSE)))
  }, striped = TRUE, hover = TRUE)
  
  output$tabla_vinculos <- renderTable({
    validate(need(nrow(notas_data()$vinc) > 0, "Sube planillas de notas."))
    notas_data()$vinc %>% transmute(Curso = etiquetar(Curso), `Nombre Notas` = Nombre_Notas, `Nombre Asistencia` = Alumno, Estado = ifelse(Vinculado, "Vinculado", "Sin coincidencia"))
  }, striped = TRUE, hover = TRUE)
  
  # Descargas
  output$descargar_notas <- downloadHandler(
    filename = function() paste0("notas_", Sys.Date(), ".csv"),
    content = function(file) escribir_csv_excel(notas_data()$det, file)
  )
  output$descargar_pdd <- downloadHandler(
    filename = function() paste0("pdd_", Sys.Date(), ".csv"),
    content = function(file) escribir_csv_excel(pdd_nomina_filtrada(), file)
  )
  output$descargar_riesgo <- downloadHandler(
    filename = function() paste0("riesgo_", Sys.Date(), ".csv"),
    content = function(file) escribir_csv_excel(maestro(), file)
  )
}

# ==============================================================================
# EJECUTAR APLICACIÓN
# ==============================================================================
shinyApp(ui = ui, server = server)
